import os, re, html, urllib.parse, unicodedata, collections, json
import numpy as np

ROOT = os.path.dirname(os.path.abspath(__file__))
SITE = os.path.join(ROOT, "site")
N = lambda s: unicodedata.normalize("NFC", s)

files = [f for f in os.listdir(SITE) if f.endswith(".html")]
bykey = {N(f).casefold(): f for f in files}
raw = {f: open(os.path.join(SITE, f), encoding="utf-8", errors="replace").read() for f in files}
redirect = {f: html.unescape(urllib.parse.unquote(m.group(1)))
            for f, t in raw.items()
            if (m := re.search(r'http-equiv="refresh" content="0; url=([^"]+)"', t))}

def canon(f):
    seen = set()
    while f in redirect and f not in seen:
        seen.add(f)
        f = bykey.get(N(redirect[f]).casefold())
        if f is None:
            return None
    return f

def resolve(href):
    f = bykey.get(N(urllib.parse.unquote(html.unescape(href))).casefold())
    return canon(f) if f else None

NONWORDS = {"index.html", "sobre.html", "contato.html"}
words = {}
for f, t in raw.items():
    if f in redirect or f in NONWORDS:
        continue
    h1 = html.unescape(re.search(r"<h1>(.*?)</h1>", t, re.S).group(1)).strip()
    tm = re.search(r'class="tema">Tema: (.*?)<', t)
    words[f] = {"word": h1, "theme": html.unescape(tm.group(1)).strip() if tm else None,
                "links": [], "seen": set()}

dangling = collections.Counter()
for f, d in words.items():
    for sid, _h, ul in re.findall(r'<section id="(\w+)"><h2>(.*?)</h2><ul>(.*?)</ul></section>', raw[f], re.S):
        for href, txt in re.findall(r'<a href="([^"]+)">(.*?)</a>', ul, re.S):
            r = resolve(href)
            label = html.unescape(re.sub("<.*?>", "", txt)).strip()
            if r is None or r not in words:
                if label:
                    dangling[(d["word"], label)] += 1
                continue
            if r == f:
                continue
            key = (words[r]["word"], sid)
            if key in d["seen"]:
                continue
            d["seen"].add(key)
            d["links"].append({"to": words[r]["word"], "type": sid, "label": label})

all_words = [d["word"] for d in words.values()]
assert len(all_words) == len(set(all_words)) == 250
word_theme = {d["word"]: d["theme"] for d in words.values()}

adj = {w: set() for w in all_words}
for f, d in words.items():
    for l in d["links"]:
        adj[d["word"]].add(l["to"])
        adj[l["to"]].add(d["word"])
pairs = {tuple(sorted((a, b))) for a in adj for b in adj[a]}
degree = {w: len(adj[w]) for w in all_words}

words_json = {w: sorted(adj[w], key=N) for w in sorted(all_words, key=N)}
with open(os.path.join(ROOT, "words.json"), "w", encoding="utf-8", newline="\n") as fh:
    json.dump(words_json, fh, ensure_ascii=False, indent=1)
    fh.write("\n")

maxdeg = max(degree.values())
top = sorted([w for w in all_words if degree[w] == maxdeg], key=N)
result = {
